import React, { useState } from 'react';
import { Link } from 'gatsby';
import { useTranslation } from 'gatsby-plugin-react-i18next';
import { FiArrowUp, FiMenu, FiX } from "react-icons/fi";
import data from '../data/data.json';
import { NavigationProps } from "../interfaces";

export default function Navigation({bg_btn}: NavigationProps) {
  const { t } = useTranslation();
  const [menuOpen, setMenuOpen] = useState(false);
  const toggleMenu = () => setMenuOpen(!menuOpen);
  const menuItems = data.menu;
  return (
    <nav className="relative">
      {/* Desktop Menu */}
      <div className="hidden md:flex gap-6 items-center text-base">
        {menuItems.map((key) => (
          <Link
            key={key}
            to={key === "about-us" ? "/" : t(`/${key}`)}
            className={`${bg_btn} text-accent text-2xl text-shadow font-bold px-4 py-2 hover:bg-accent hover:text-white`}
          >
            {t(`menu.${key}`)}
          </Link>
        ))}
      </div>

      {/* Mobile Menu Button */}
      <div className={"md:hidden flex items-center text-accent"}>
        <button onClick={toggleMenu} aria-label="Toggle menu" className=''>
          {menuOpen ? <FiX size={36} /> : <FiMenu size={36} />}
        </button>
      </div>

      {/* Mobile Menu Panel */}
      {menuOpen && (
        <div className="fixed left-0 top-0 w-full h-1/2 bg-white text-center shadow-md p-4 z-[150] flex flex-col gap-4 md:hidden">
          {menuItems.map((key) => (
            <Link
              key={key}
              to={key === "about-us" ? "/" : t(`/${key}`)}
              className="hover:text-accent transition-colors"
              onClick={() => setMenuOpen(false)} // Close on click
            >
              {t(key)}
            </Link>
          ))}
        </div>
      )}
    </nav>
  );
};
